            aCross = (RotL64(aFuseLaneB[((S_BLOCK1 - aIndex + 29128U)) & S_BLOCK1], 20U) ^ RotL64(aWaterLaneD[((S_BLOCK1 - aIndex + 30353U)) & S_BLOCK1], 5U));
