            aOrbiterH = ((aWandererD + RotL64(aCross, 3U)) + RotL64(aCarry, 43U)) + 0x5507BB6F59D83B72ULL;
            aOrbiterI = ((aWandererK + RotL64(aScatter, 35U)) + RotL64(aCarry, 21U)) + 0x91B25B406AF6C5D2ULL;
            aOrbiterF = ((aWandererH + RotL64(aPrevious, 43U)) + 0x1B22F0246429A9F0ULL) + aTwistOrbiterAssignSaltD[((aIndex + 199U)) & S_SALT1];
            aOrbiterA = (((aWandererA + RotL64(aIngress, 21U)) + RotL64(aCarry, 57U)) + 0x9ADD4EB6D56A91A5ULL) + aTwistOrbiterAssignSaltF[((aIndex + 33U)) & S_SALT1];
            aOrbiterD = (aWandererC + RotL64(aCross, 13U)) + 0x8567354C5DB95FA5ULL;
