            aOrbiterD = (aOrbiterD + aOrbiterC) + 0xA1CA2ADEB862CCE1ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterD) ^ 0x2A6AF60440DC12EBULL;
