            //
            aOrbiterI = (aOrbiterI + aOrbiterF) + 0x96F50FB0D8BB9467ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterI) ^ 0xBA23170ECE83381EULL;
            aOrbiterA = RotL64((aOrbiterA * 0x1DA54A8D1FB0C933ULL), 29U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterA) + 0xEE2A465165F91A3AULL) + aTwistOrbiterUpdateSaltA[(((255U - aIndex) + 112U)) & S_SALT1];
