            aIngress = aIngress + RotL64(aOrbiterH, 57U);
            aIngress = TwistMix64::DiffuseB((aIngress + aScatter));
            //
            aWandererH = aWandererH ^ ((RotL64(aIngress, 50U) + RotL64(aOrbiterD, 20U)) + aOrbiterC);
            aWandererB = aWandererB + (((RotL64(aCross, 3U) + RotL64(aOrbiterD, 57U)) + aOrbiterI) + aTwistWandererUpdateSaltF[((aIndex + 46U)) & S_SALT1]);
            aWandererC = aWandererC ^ ((RotL64(aScatter, 21U) + RotL64(aOrbiterF, 41U)) + aOrbiterI);
