            aWandererK = aWandererK ^ (((RotL64(aCross, 35U) + RotL64(aOrbiterD, 27U)) + aOrbiterJ) + aTwistWandererUpdateSaltD[(((255U - aIndex) + 237U)) & S_SALT1]);
