            aCross ^= RotL64(aFireLaneC[((aIndex + 8796U)) & S_BLOCK1], 35U);
            aCross = TwistMix64::DiffuseB((aCross ^ aTwistDomainWordCross));
            //
            aScatter = (RotL64(aCarry, 29U) ^ RotL64(aIngress, 58U)) + (RotL64(aPrevious, 11U) ^ RotL64(aCross, 43U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterA = ((aWandererD + RotL64(aIngress, 43U)) + RotL64(aCarry, 41U)) + 0x33F5CC6397C2A530ULL;
