            //
            aIngress = (RotL64(aIceLaneD[((aIndex + 6960U)) & S_BLOCK1], 47U) ^ RotL64(aIceLaneB[((aIndex + 7564U)) & S_BLOCK1], 5U));
            aIngress ^= (RotL64(pCrossLaneD[((aIndex + 2009U)) & S_BLOCK1], 21U) ^ RotL64(aWaterLaneB[((S_BLOCK1 - aIndex + 7513U)) & S_BLOCK1], 56U));
