            aOrbiterD = (aWandererG + RotL64(aCross, 4U)) + 0x2EF5C75DC538EE2BULL;
            aOrbiterH = (aWandererE + RotL64(aScatter, 23U)) + 0xABEB6BB5BD74D7E4ULL;
            aOrbiterB = ((aWandererH + RotL64(aCross, 13U)) + 0x16BD927B33678EC2ULL) + aTwistOrbiterAssignSaltF[((aIndex + 60U)) & S_SALT1];
