            //
            aIngress = (RotL64(aFuseLaneC[((aIndex + 32123U)) & S_BLOCK1], 24U) ^ RotL64(aFuseLaneA[((aIndex + 28803U)) & S_BLOCK1], 3U));
            aIngress ^= (RotL64(aLightningLaneD[((aIndex + 29085U)) & S_BLOCK1], 47U) ^ RotL64(aHeartLaneD[((aIndex + 24794U)) & S_BLOCK1], 35U));
