            aCross ^= (RotL64(aLightningLaneA[((S_BLOCK1 - aIndex + 29142U)) & S_BLOCK1], 13U) ^ RotL64(aHeartLaneC[((S_BLOCK1 - aIndex + 26595U)) & S_BLOCK1], 58U));
