            //
            aScatter = (RotL64(aIngress, 43U) + RotL64(aCross, 57U)) + (RotL64(aCarry, 28U) ^ RotL64(aPrevious, 11U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterC = (aWandererI + RotL64(aIngress, 19U)) + 0x733E8FCAAFEB11ECULL;
            aOrbiterD = ((aWandererH + RotL64(aScatter, 52U)) + RotL64(aCarry, 3U)) + 0xDD51E1C48969D3E8ULL;
            aOrbiterH = (aWandererC + RotL64(aPrevious, 3U)) + 0x926B23E421CF4ACDULL;
            aOrbiterF = ((aWandererK + RotL64(aCross, 11U)) + 0x42214F1B0FA0E307ULL) + aTwistOrbiterAssignSaltC[(((255U - aIndex) + 22U)) & S_SALT1];
