            aOrbiterJ = ((aWandererD + RotL64(aCross, 56U)) + RotL64(aCarry, 39U)) + 0x346E0A23C425A942ULL;
            aOrbiterA = (aWandererB + RotL64(aScatter, 47U)) + 0x775AA8F74B91CF2FULL;
            aOrbiterE = ((aWandererE + RotL64(aPrevious, 43U)) + RotL64(aCarry, 53U)) + 0x6223A0216909F5E4ULL;
            aOrbiterK = ((aWandererF + RotL64(aIngress, 29U)) + 0x990B36F7CF81AFBAULL) + aTwistOrbiterAssignSaltF[(((255U - aIndex) + 210U)) & S_SALT1];
            //
            aOrbiterC = (aOrbiterC + aOrbiterD) + 0x9288B86F989F682AULL;
