            //
            aOrbiterJ = (aOrbiterJ + aOrbiterC) + 0x0A33E6D46E26C627ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterJ) ^ 0x7D57BBCE4D591136ULL;
            aOrbiterA = RotL64((aOrbiterA * 0xAC2DC8729A495821ULL), 19U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterJ) + 0x7ECDDAED0A9D8E7EULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterI) ^ 0x417F0C63D3242C94ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x534EFA93BB76A445ULL), 47U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterK) + 0x777587BFB26CC493ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterE) ^ 0xFE7306F446C6DDA0ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x422CF74AF1D67149ULL), 53U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterA) + 0x50A9276B7ED8D227ULL) + aTwistOrbiterUpdateSaltD[((aIndex + 83U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterD) ^ 0x2E84A19964D0F0DDULL;
            aOrbiterE = RotL64((aOrbiterE * 0x9F946DC7BAEA69D3ULL), 39U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterH) + 0x9CAAE10DCD2349CAULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterA) ^ 0x4B7367B493609972ULL) ^ aTwistOrbiterUpdateSaltA[((aIndex + 240U)) & S_SALT1];
