            //
            aOrbiterK = ((aOrbiterK + aOrbiterF) + 0xD769C95333289BB5ULL) + aTwistOrbiterUpdateSaltF[(((255U - aIndex) + 59U)) & S_SALT1];
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterK) ^ 0x248B91216C991A78ULL) ^ aTwistOrbiterUpdateSaltE[((aIndex + 181U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x5A4F7BFA23334519ULL), 43U);
