            //
            aCross = (RotL64(aWoodLaneC[((S_BLOCK1 - aIndex + 3357U)) & S_BLOCK1], 3U) ^ RotL64(aWoodLaneD[((S_BLOCK1 - aIndex + 5348U)) & S_BLOCK1], 51U));
