            //
            aOrbiterG = ((aWandererB + RotL64(aPrevious, 3U)) + 0x53645F6E9F322A7FULL) + aTwistOrbiterAssignSaltC[(((255U - aIndex) + 165U)) & S_SALT1];
            aOrbiterH = ((aWandererE + RotL64(aCross, 21U)) + RotL64(aCarry, 53U)) + 0xBB1DABC421128EC1ULL;
            aOrbiterI = (aWandererF + RotL64(aIngress, 27U)) + 0xC30C4768885A1146ULL;
            aOrbiterJ = ((aWandererG + RotL64(aScatter, 57U)) + RotL64(aCarry, 39U)) + 0x6F98130DDE68D2DEULL;
            aOrbiterA = (((aWandererH + RotL64(aIngress, 42U)) + RotL64(aCarry, 27U)) + 0x76C7820ADD57EB43ULL) + aTwistOrbiterAssignSaltD[((aIndex + 17U)) & S_SALT1];
            aOrbiterE = (aWandererD + RotL64(aPrevious, 13U)) + 0xBF83CAA0257E2372ULL;
            aOrbiterB = (aWandererK + RotL64(aScatter, 35U)) + 0x95305D8ADEEC4D38ULL;
            //
            aOrbiterG = (aOrbiterG + aOrbiterH) + 0x7BC93DBE4515B4A4ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterG) ^ 0x716F69D9A6D6DBC3ULL;
