            //
            aOrbiterH = (aOrbiterH + aOrbiterJ) + 0x6DF9BE9F372141F3ULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterH) ^ 0x4D95682B3E1C3DBBULL) ^ aTwistOrbiterUpdateSaltA[(((255U - aIndex) + 160U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0x4D4248524EF27555ULL), 13U);
