            aOrbiterA = (aOrbiterA + aOrbiterG) + 0x9DFA0E4625171107ULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterA) ^ 0xE18152B3A96DC84DULL) ^ aTwistOrbiterUpdateSaltE[((aIndex + 59U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0xA7B40907DE7A1AA7ULL), 57U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterA) + 0xF8E8FE81CFBDCDDEULL;
