            aOrbiterG = ((aOrbiterG ^ aOrbiterJ) ^ 0x184058F524E581C5ULL) ^ aTwistOrbiterUpdateSaltF[((aIndex + 62U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0x82ECA79639252E5DULL), 27U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterI) + 0x1B3F9286F7D546BAULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterE) ^ 0x23047319FB375266ULL;
