            aOrbiterD = (((aWandererH + RotL64(aCross, 3U)) + RotL64(aCarry, 53U)) + 0x3813D04FC92B23B8ULL) + aKeyRotateAOrbiterAssignSaltA[(((255U - aIndex) + 1U)) & S_SALT1];
