            aOrbiterD = ((aWandererD + RotL64(aCross, 18U)) + RotL64(aCarry, 5U)) + 0x6528A3BAA69A44BDULL;
            aOrbiterK = (aWandererJ + RotL64(aScatter, 37U)) + 0xD028F8F61538D481ULL;
            aOrbiterA = ((aWandererB + RotL64(aPrevious, 47U)) + RotL64(aCarry, 13U)) + 0x5D214A2F227ABF34ULL;
            aOrbiterI = (aWandererF + RotL64(aIngress, 3U)) + 0xF12A86CC958344F9ULL;
            aOrbiterE = (((aWandererK + RotL64(aScatter, 28U)) + RotL64(aCarry, 51U)) + 0xB0BC1A08D60893C6ULL) + aKeyRotateBOrbiterAssignSaltE[((aIndex + 162U)) & S_SALT1];
            //
            aOrbiterB = (aOrbiterB + aOrbiterJ) + 0xBD0DBBB8724C7766ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterB) ^ 0x510B612FD28C3AE2ULL;
