            aOrbiterG = ((aOrbiterG + aOrbiterA) + 0x77E35A3AA29EBABBULL) + aKeyRotateBOrbiterUpdateSaltA[(((255U - aIndex) + 253U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterG) ^ 0xEA6FD2CB8BA56C72ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x34ADD013949D0C27ULL), 43U);
