            aWandererG = aWandererG + (((RotL64(aCross, 3U) + RotL64(aOrbiterJ, 47U)) + aOrbiterH) + RotL64(aCarry, 11U));
            aWandererF = aWandererF ^ ((RotL64(aIngress, 57U) + RotL64(aOrbiterC, 39U)) + aOrbiterB);
            aWandererJ = aWandererJ + ((RotL64(aScatter, 35U) + aOrbiterE) + RotL64(aOrbiterB, 35U));
            aWandererE = aWandererE ^ ((RotL64(aPrevious, 18U) + RotL64(aOrbiterH, 30U)) + aOrbiterK);
            aWandererK = aWandererK + ((RotL64(aIngress, 43U) + aOrbiterA) + RotL64(aOrbiterC, 23U));
            //
            aCarry = aCarry + (RotL64(aWandererE, 57U) ^ aWandererJ);
