            //
            aOrbiterB = ((aOrbiterB + aOrbiterJ) + 0xEFDEB9301BB270C2ULL) + aKeyRotateBOrbiterUpdateSaltC[(((255U - aIndex) + 185U)) & S_SALT1];
            aOrbiterK = ((aOrbiterK ^ aOrbiterB) ^ 0x0D070E57F1C3142DULL) ^ aKeyRotateBOrbiterUpdateSaltD[(((255U - aIndex) + 121U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0x5FD74355B325B6D9ULL), 35U);
