            aWandererG = aWandererG ^ ((RotL64(aCross, 13U) + RotL64(aOrbiterB, 5U)) + aOrbiterG);
            aWandererH = aWandererH + ((RotL64(aPrevious, 53U) + RotL64(aOrbiterH, 21U)) + aOrbiterI);
            aWandererI = aWandererI ^ ((RotL64(aScatter, 23U) + aOrbiterG) + RotL64(aOrbiterJ, 53U));
            //
            aCarry = aCarry + (RotL64(aWandererC, 35U) ^ aWandererA);
            aCarry = aCarry + (RotL64(aWandererG, 3U) ^ aWandererJ);
