            aCross ^= (RotL64(aKineticLaneD[((S_BLOCK1 - aIndex + 12034U)) & S_BLOCK1], 35U) ^ RotL64(aAetherLaneC[((aIndex + 14507U)) & S_BLOCK1], 13U));
            aCross = TwistMix64::DiffuseB((aCross ^ aKeyRotateBDomainWordCross));
