            aScatter = (RotL64(aCross, 27U) ^ RotL64(aIngress, 11U)) + (RotL64(aPrevious, 58U) + RotL64(aCarry, 41U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aKeyRotateBDomainWordScatter));
            //
            aOrbiterC = (aWandererF + RotL64(aPrevious, 23U)) + 0x17E7F3BA6C349475ULL;
            aOrbiterA = (((aWandererD + RotL64(aCross, 47U)) + RotL64(aCarry, 47U)) + 0xD5F98FC5B3B52C41ULL) + aKeyRotateBOrbiterAssignSaltC[((aIndex + 221U)) & S_SALT1];
            aOrbiterG = (aWandererA + RotL64(aIngress, 11U)) + 0x9E2218404CE72B24ULL;
            aOrbiterJ = ((aWandererI + RotL64(aScatter, 5U)) + RotL64(aCarry, 27U)) + 0xD6C8768FBBD5B3CCULL;
            aOrbiterE = ((aWandererE + RotL64(aIngress, 26U)) + RotL64(aCarry, 23U)) + 0x51631AE344BAA196ULL;
            aOrbiterB = ((aWandererG + RotL64(aScatter, 41U)) + 0x69D9DF433E13B652ULL) + aKeyRotateBOrbiterAssignSaltB[((aIndex + 15U)) & S_SALT1];
            aOrbiterH = (aWandererJ + RotL64(aCross, 37U)) + 0x077CD4316A74B9D2ULL;
            aOrbiterI = (aWandererB + RotL64(aPrevious, 53U)) + 0x30350CB93DE8B39BULL;
            aOrbiterD = (aWandererH + RotL64(aIngress, 19U)) + 0xAE49224BC16AEEA1ULL;
